// Writes src/lib/parse/cifReference.gen.ts and src/lib/parse/ccdCategories.gen.ts
// from the reference lists the Go parser embeds (lib/cif/cofactors.json,
// metal_ions.json, solvents.json, covalent_cofactors.json and ccd_types.json),
// so the browser preview and the backend sort compounds with the same lists.
// The CCD categories get a module of their own: the entry form reads the lists
// and must not load the 4,000-ID table only the preview parser needs.
//
//   npm run gen:cif-reference          rewrite the generated files
//   node scripts/gen-cif-reference.mjs --check   exit 1 when one is out of date
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const websiteRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const cifRoot = join(websiteRoot, "..", "lib", "cif");
const outputDir = join(websiteRoot, "src", "lib", "parse");

const FILES = [
  "cofactors.json",
  "metal_ions.json",
  "solvents.json",
  "covalent_cofactors.json",
  "ccd_types.json",
];

// The CCD categories are long, so they are wrapped like the JSON they come from.
const IDS_PER_LINE = 16;

function readJSON(name) {
  return JSON.parse(readFileSync(join(cifRoot, name), "utf8"));
}

function quoted(values) {
  return values.map((value) => JSON.stringify(String(value).toUpperCase()));
}

function list(values) {
  return `[${quoted(values).join(", ")}]`;
}

function wrappedList(values) {
  const lines = [];
  const items = quoted(values);
  for (let start = 0; start < items.length; start += IDS_PER_LINE) {
    lines.push(`    ${items.slice(start, start + IDS_PER_LINE).join(", ")},`);
  }
  return lines.length === 0 ? "[]" : `[\n${lines.join("\n")}\n  ]`;
}

function stringArray(file, name, key) {
  const values = file[key];
  if (!Array.isArray(values) || values.some((value) => typeof value !== "string")) {
    throw new Error(`${name} has no string array "${key}"`);
  }
  return values;
}

/** The generated files, by name in src/lib/parse. */
export function generate() {
  const files = Object.fromEntries(FILES.map((name) => [name, readJSON(name)]));
  for (const [name, file] of Object.entries(files)) {
    if (typeof file.version !== "string" || file.version.trim() === "") {
      throw new Error(`${name} has no version`);
    }
    if (typeof file.approved !== "boolean") {
      throw new Error(`${name} has no boolean "approved" flag`);
    }
    if (typeof file.ccd_checked !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(file.ccd_checked)) {
      throw new Error(`${name} has no "ccd_checked" date`);
    }
  }
  const cofactors = files["cofactors.json"];
  const metalIons = files["metal_ions.json"];
  const solvents = files["solvents.json"];
  const covalent = files["covalent_cofactors.json"];
  const ccdTypes = files["ccd_types.json"];
  const approved = Object.values(files).every((file) => file.approved);
  // The same string as Reference.Version in lib/cif/reference.go.
  const referenceVersion =
    `cofactors:${cofactors.version}+metals:${metalIons.version}+solvents:${solvents.version}` +
    `+covalent:${covalent.version}+ccd-types:${ccdTypes.version}`;
  const covalentMap = covalent.covalent_cofactors
    .map((pair) => `${JSON.stringify(pair.residue.toUpperCase())}: ${JSON.stringify(pair.cofactor.toUpperCase())}`)
    .join(", ");

  const reference = `// Code generated by scripts/gen-cif-reference.mjs from the reference lists in
// lib/cif (cofactors.json, metal_ions.json, solvents.json,
// covalent_cofactors.json, ccd_types.json). DO NOT EDIT: change the JSON files
// and run \`npm run gen:cif-reference\`.

export const CIF_REFERENCE = {
  cofactorVersion: ${JSON.stringify(cofactors.version)},
  metalIonVersion: ${JSON.stringify(metalIons.version)},
  solventVersion: ${JSON.stringify(solvents.version)},
  covalentCofactorVersion: ${JSON.stringify(covalent.version)},
  ccdTypeVersion: ${JSON.stringify(ccdTypes.version)},
  /** Every list version, as the backend parser reports it (reference_version). */
  referenceVersion: ${JSON.stringify(referenceVersion)},
  /** True only when researchers approved every list. */
  approved: ${approved},
  cofactors: ${list(cofactors.cofactors.map((cofactor) => cofactor.id))},
  metalIons: ${list(stringArray(metalIons, "metal_ions.json", "metal_ions"))},
  solvents: ${list(stringArray(solvents, "solvents.json", "solvents"))},
  /** Often from the buffer, often a real ligand: kept and flagged. */
  ambiguous: ${list(stringArray(solvents, "solvents.json", "ambiguous"))},
  /** On the solvent list, but kept when a metalc row binds them to a metal. */
  keepWhenMetalLinked: ${list(stringArray(solvents, "solvents.json", "keep_when_metal_linked"))},
  /** Modified residue → the cofactor bound covalently in it. */
  covalentCofactors: { ${covalentMap} },
  metalElements: ${list(stringArray(cofactors, "cofactors.json", "metal_elements"))},
  nonmetalElements: ${list(stringArray(cofactors, "cofactors.json", "nonmetal_elements"))},
} as const;
`;
  const ccdCategories = `// Code generated by scripts/gen-cif-reference.mjs from lib/cif/ccd_types.json.
// DO NOT EDIT: change the JSON file and run \`npm run gen:cif-reference\`.

/** CCD IDs whose type is a peptide, nucleotide or saccharide type. */
export const CCD_CATEGORIES: Readonly<Record<"peptide" | "nucleotide" | "saccharide", readonly string[]>> = {
  peptide: ${wrappedList(stringArray(ccdTypes, "ccd_types.json", "peptide"))},
  nucleotide: ${wrappedList(stringArray(ccdTypes, "ccd_types.json", "nucleotide"))},
  saccharide: ${wrappedList(stringArray(ccdTypes, "ccd_types.json", "saccharide"))},
};
`;
  return { "cifReference.gen.ts": reference, "ccdCategories.gen.ts": ccdCategories };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  for (const [name, generated] of Object.entries(generate())) {
    const outputPath = join(outputDir, name);
    if (!process.argv.includes("--check")) {
      writeFileSync(outputPath, generated);
    } else if (readFileSync(outputPath, "utf8") !== generated) {
      console.error(`src/lib/parse/${name} is out of date: run \`npm run gen:cif-reference\``);
      process.exitCode = 1;
    }
  }
}
